KG42.register("rules-5fe47103901b4c42f1046cad",{"id":"34-market_versus_price_scheduling::v141-c-R010","paper":"34-market_versus_price_scheduling","record":{"rule_id":"v141-c-R010","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"Positive power-transfer deviations incur a penalty based on the market price or a relatively larger value. Scope: Proposed market-based microgrid scheduling under the positive-deviation-only penalty regime. Condition: The microgrid’s scheduled power exceeds the power assigned by the DMO. Negative power-transfer deviations incur no deviation penalty. Scope: Proposed market-based microgrid scheduling under the positive-deviation-only penalty regime. Condition: The power-transfer deviation from DMO-assigned power is negative. The absolute power-transfer deviation is penalized, including deviations resulting in a surplus of power. Scope: Examined absolute-deviation penalty alternative in market-based microgrid scheduling. Condition: The absolute value of power-transfer deviation is selected as the penalty basis.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["settlement.payment"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Examined absolute-deviation penalty alternative in market-based microgrid scheduling. | Proposed market-based microgrid scheduling under the positive-deviation-only penalty regime.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e025","v141-b-g02-E29"]},"x":[{"variable_id":"x_pm_scheduled","symbol":"P^M_{mt}","meaning":"Scheduled power transfer from the DMO to microgrid m at hour t; the microgrid scheduling decision whose deviation from the DMO assignment triggers the settlement penalty.","kind":"operational","domain":"\\mathbb{R}","unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e018","v141-b-g01-e021","v141-b-g01-e022"]},{"variable_id":"x_delta_pm_deviation","symbol":"\\Delta P^M_{mt}","meaning":"Power-transfer deviation for microgrid m at hour t, defined as scheduled main-grid transfer minus DMO-assigned demand.","kind":"operational","domain":"\\mathbb{R}","unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e022","v141-b-g01-e027"]},{"variable_id":"x_delta_pm_positive","symbol":"\\Delta P^{M+}_{mt}","meaning":"Positive power-transfer deviation selected for penalty in the settlement payment term.","kind":"operational","domain":"\\mathbb{R}_{\\ge 0}","unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e018","v141-b-g01-e023"]},{"variable_id":"x_delta_indicator","symbol":"\\delta_{mt}","meaning":"Binary indicator equal to 1 when the power-transfer deviation is positive and 0 otherwise, used to select the penalized positive deviation.","kind":"operational","domain":"\\{0,1\\}","unit":null,"indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e027"]}],"theta":[{"parameter_id":"theta_nu_penalty","symbol":"\\nu_m","meaning":"Penalty coefficient for scheduled positive power deviation of microgrid m; the source states it is based on the market price or a relatively larger value.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["m"],"evidence_ids":["v141-b-g01-e004","v141-b-g01-e018","v141-b-g01-e025"]},{"parameter_id":"theta_pdm_assigned","symbol":"PD^M_{mt}","meaning":"Assigned demand/power to microgrid m by the DMO at hour t; the reference value for computing the power-transfer deviation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"MW","indices":["m","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g01-e022","v141-b-g01-e034"]},{"parameter_id":"theta_pm_max","symbol":"P^{M,\\max}","meaning":"Maximum main-grid power transfer limit for microgrid m, used to bound the deviation-selection constraints.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"MW","indices":["m"],"evidence_ids":["v141-b-g01-e021","v141-b-g01-e023","v141-b-g01-e024"]},{"parameter_id":"theta_epsilon","symbol":"\\varepsilon","meaning":"Small positive constant in Eq. (10) used to enforce the one-sided positive-deviation penalty branch.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e024"]}],"phi":[{"constraint_id":"v141-c-R010-C001","kind":"mathematical","role":"core","statement":"Positive power-transfer deviations incur a penalty based on the market price or a relatively larger value. Scope: Proposed market-based microgrid scheduling under the positive-deviation-only penalty regime. Condition: The microgrid’s scheduled power exceeds the power assigned by the DMO.","expression":"\\nu_m \\Delta P^{M+}_{mt} \\quad \\text{when } \\Delta P^M_{mt} > 0","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_pm_scheduled","x_delta_pm_deviation","x_delta_pm_positive"],"parameter_refs":["theta_nu_penalty","theta_pdm_assigned"],"evidence_ids":["v141-b-g01-e025","v141-b-g01-e004","v141-b-g01-e018","v141-b-g01-e022","v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e027"]},{"constraint_id":"v141-c-R010-C002","kind":"mathematical","role":"core","statement":"Negative power-transfer deviations incur no deviation penalty. Scope: Proposed market-based microgrid scheduling under the positive-deviation-only penalty regime. Condition: The power-transfer deviation from DMO-assigned power is negative.","expression":"\\Delta P^M_{mt} \u003c 0 \\;\\Rightarrow\\; \\Delta P^{M+}_{mt}=0","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_delta_pm_deviation","x_delta_pm_positive"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e025","v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e027"]},{"constraint_id":"v141-c-R010-C003","kind":"mathematical","role":"core","statement":"The absolute power-transfer deviation is penalized, including deviations resulting in a surplus of power. Scope: Examined absolute-deviation penalty alternative in market-based microgrid scheduling. Condition: The absolute value of power-transfer deviation is selected as the penalty basis.","expression":"|\\Delta P^M_{mt}|","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_delta_pm_deviation"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E29"]},{"constraint_id":"v141-c-R010-C004","kind":"mathematical","role":"supporting","statement":"The power-transfer deviation is the scheduled main-grid transfer minus the DMO-assigned demand.","expression":"\\Delta P^M_{mt} = P^M_{mt} - PD^M_{mt} \\quad \\forall t","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_pm_scheduled","x_delta_pm_deviation"],"parameter_refs":["theta_pdm_assigned"],"evidence_ids":["v141-b-g01-e022","v141-b-g01-e027"]},{"constraint_id":"v141-c-R010-C005","kind":"mathematical","role":"supporting","statement":"The positive-deviation selection is enforced by the binary indicator delta: when delta is zero the penalized quantity is zero; when delta is one the penalized quantity equals the positive deviation.","expression":"-P^{M,\\max} \\delta_{mt} \\le \\Delta P^{M+}_{mt} \\le P^{M,\\max} \\delta_{mt} \\quad \\forall t;\\n-P^{M,\\max}(1-\\delta_{mt}) \\le \\Delta P^M_{mt} - \\Delta P^{M+}_{mt} \\le P^{M,\\max}(1-\\delta_{mt}) \\quad \\forall t;\\n-P^{M,\\max}(1-\\delta_{mt}) + \\varepsilon \\le \\Delta P^M_{mt} \\le P^{M,\\max} \\delta_{mt} \\quad \\forall t","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x_delta_pm_deviation","x_delta_pm_positive","x_delta_indicator"],"parameter_refs":["theta_pm_max","theta_epsilon"],"evidence_ids":["v141-b-g01-e023","v141-b-g01-e024","v141-b-g01-e027"]}],"pi":[{"evidence_id":"v141-b-g01-e025","location":{"location_id":"src-b66ae5184e-p04-c2r1__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Model Outline","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 2, MARCH 2018 the assigned value will be penalized base","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"It will be assumed that deviations from the assigned value will be penalized based on the market price or a relatively larger value that can effectively prevent and/or reduce deviations. In this paper, it is assumed that the penalty will be applied when the deviation is positive, i.e., the microgrid’s scheduled power is larger than the assigned power by the DMO, or in other words, when the microgrid appears as a larger load compared to the assigned power by the DMO. Negative deviation will not be penalized in the proposed model as the microgrid helps with reducing load (increasing generation) in the distribution network."},{"evidence_id":"v141-b-g02-E29","location":{"location_id":"src-b66ae5184e-p08-c2r1__v141-a-M01-pricing","page":8,"printed_page":null,"section":"V. Numerical Simulations","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 9, NO. 2, MARCH 2018 hours and uses its own resources that bec","equation_id":null,"figure_id":"Fig. 8","table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"When the absolute value of the deviations is penalized, the total microgrid operation cost rises to $50,539, as microgrid is obligated to closely follow the scheduled power transfer and hence would reduce generation of some its resources to purchase more power from the main grid, which results in a higher operation cost. This shows that penalizing power deviation is key to ensuring certainty in the power scheduled by the DMO. Penalizing the absolute value of power deviation can increase the microgrid operation cost, even if the power deviation would result in a surplus of power which is manageable by the system operator. The decision to penalize only the positive deviations or the absolute deviation should be made by the distribution system operator based on the probable congestion scenarios."},{"evidence_id":"v141-b-g01-e003","location":{"location_id":"src-b66ae5184e-p01-c2r3__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"DXmax Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"d Load demand. D The demand awarded from the ISO to the DMO. PD^M Assigned demand to microgrids by the DMO. DX The amount of load awarded to each segment of the bid. DX^max Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 when committed, 0 otherwise). LS Load curtailment. P DER output power. P^M Scheduled power transfer from the DMO to the microgrid. PL Line flow. \\Delta P^M Power transfer deviation. \\Delta P^{M+} Positive power transfer deviation. \\delta Power transfer deviation indicator (1 when deviation is positive, 0 otherwise). \\theta Bus angle."},{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b66ae5184e-p01-c2r2__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"ar- U Islanding indicator (1 when grid-connected, on 0 when islanded). his ν Penalty for scheduled p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"U Islanding indicator (1 when grid-connected, 0 when islanded). \\nu Penalty for scheduled power deviation. \\upsilon Value of lost load. x Line impedance. \\rho(P) Cost function of generation units submitted to the ISO. \\lambda(D) Consumption benefit of aggregated loads."},{"evidence_id":"v141-b-g01-e018","location":{"location_id":"src-b66ae5184e-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"li- SCHEDULING PROBLEM FORMULATION ity The discussed three levels of the market structure are her fo","equation_id":"Eqs. (1)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"\\min \\sum_t \\sum_i \\left[ F_{im}(P_{imt}, I_{imt}) + \\upsilon_m LS_{mt} + \\nu_m \\Delta P^{M+}_{mt} \\right] \\quad (1)"},{"evidence_id":"v141-b-g01-e021","location":{"location_id":"src-b66ae5184e-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"he t i MO PMmt + Pimt + LSmt = dmt ∀t (2) ent i us- Pminim Iimt ≤Pimt ≤Pmaxim Iimt ∀t, ∀i (3) nd, v-","equation_id":"Eqs. (2)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"-P^{M,max}_m U_{mt} \\le P^M_{mt} \\le P^{M,max}_m U_{mt} \\quad \\forall t \\quad (6)"},{"evidence_id":"v141-b-g01-e022","location":{"location_id":"src-b66ae5184e-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"he t i MO PMmt + Pimt + LSmt = dmt ∀t (2) ent i us- Pminim Iimt ≤Pimt ≤Pmaxim Iimt ∀t, ∀i (3) nd, v-","equation_id":"Eqs. (2)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"\\Delta P^M_{mt} = P^M_{mt} - PD^M_{mt} \\quad \\forall t \\quad (7)"},{"evidence_id":"v141-b-g01-e023","location":{"location_id":"src-b66ae5184e-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Microgrid","anchor_text":"he t i MO PMmt + Pimt + LSmt = dmt ∀t (2) ent i us- Pminim Iimt ≤Pimt ≤Pmaxim Iimt ∀t, ∀i (3) nd, v-","equation_id":"Eqs. (2)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"-P^{M,max}\\delta_{mt} \\le \\Delta P^{M+}_{mt} \\le P^{M,max}\\delta_{mt} \\quad \\forall t \\quad (8)\\n-P^{M,max}(1-\\delta_{mt}) \\le \\Delta P^M_{mt} - \\Delta P^{M+}_{mt} \\le P^{M,max}(1-\\delta_{mt}) \\quad \\forall t \\quad (9)"},{"evidence_id":"v141-b-g01-e024","location":{"location_id":"src-b66ae5184e-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"A. Microgrid","anchor_text":"PARHIZI et al.: MARKET-BASED VERSUS PRICE-BASED MICROGRID OPTIMAL SCHE −PM,max(1 −δmt) + ε ≤ PMmt ≤P","equation_id":"Eq. (10)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"-P^{M,max}(1-\\delta_{mt}) + \\varepsilon \\le \\Delta P^M_{mt} \\le P^{M,max}\\delta_{mt} \\quad \\forall t \\quad (10)"},{"evidence_id":"v141-b-g01-e027","location":{"location_id":"src-b66ae5184e-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"A. Microgrid","anchor_text":"its associated limits (imposed by the capacity of the line connecting the microgrid to the main grid","equation_id":"Eqs. (7)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The main grid power transfer is restricted by its associated limits (imposed by the capacity of the line connecting the microgrid to the main grid) in (6). The islanding is modeled using a binary islanding indicator U which would zero out the main grid power transfer when 0. The main grid power deviation to be penalized in the objective is determined in (7)-(10). Constraint (7) calculates the deviation by subtracting the scheduled power via the optimal scheduling, PM, by the assigned power from the DMO, PDM. Constraints (8)-(10) determine the penalty if the calculated deviation is positive. An auxiliary binary variable δ is used for this purpose. When δ = 0 the power transfer to be penalized is zero, i.e., the scheduled power is less than the assigned power. However, when δ = 1 the power transfer to be penalized is equal to the positive deviation calculated in (7)."},{"evidence_id":"v141-b-g01-e034","location":{"location_id":"src-b66ae5184e-p05-c2r4__v141-a-M01-matching","page":5,"printed_page":null,"section":"B. DMO / 2) Quantity Disaggregation","anchor_text":"ne max cmjDXmjt (12) d- t m j ch DXmjt ≤DXmaxmj ∀m, ∀t, ∀j (13) he ec- drmt = DXmjt ∀m, ∀t (14) he j","equation_id":"Eqs. (12)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"DX_{mjt} \\le DX^{max}_{mj} \\quad \\forall m, \\forall t, \\forall j \\quad (13)\\nd^r_{mt} = \\sum_j DX_{mjt} \\quad \\forall m, \\forall t \\quad (14)\\nd^f_{mt} + d^r_{mt} = PD^M_{mt} \\quad \\forall m, \\forall t \\quad (15)\\n\\sum_m PD^M_{mt} = D_{bt} \\quad \\forall t \\quad (16)"}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-pricing"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e025","quote":"deviations from the assigned value will be penalized based on the market price or a relatively larger value that can effectively prevent and/or reduce deviations."},{"evidence_id":"v141-b-g01-e025","quote":"the penalty will be applied when the deviation is positive, i.e., the microgrid’s scheduled power is larger than the assigned power by the DMO"}],[{"evidence_id":"v141-b-g01-e025","quote":"Negative deviation will not be penalized in the proposed model as the microgrid helps with reducing load (increasing generation) in the distribution network."}],[{"evidence_id":"v141-b-g02-E29","quote":"When the absolute value of the deviations is penalized"},{"evidence_id":"v141-b-g02-E29","quote":"Penalizing the absolute value of power deviation can increase the microgrid operation cost, even if the power deviation would result in a surplus of power which is manageable by the system operator."}]],"C2_formalization":{"graph_sha256":"70933de54675ad97c74d0de2acb4c1194145c7ca6c1ca815ab632055228e47b8","applicability":"formalized","reason":"Formalized the settlement payment penalty as the positive-deviation penalty term ν_m ΔP^{M+}_{mt}, with Eq. (7) defining the deviation and Eqs. (8)-(10) selecting the positive part; preserved the negative-deviation exemption and the alternative absolute-deviation basis. The frozen graph contains only settlement.payment, so all bindings attach to that function node; no edges were available or needed. B evidence remains unreviewed and this formalization is provisional.","bindings":[{"object_id":"x_pm_scheduled","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"P^M_{mt} is the scheduled main-grid power transfer whose deviation from the DMO assignment triggers the settlement.payment penalty; it is an input to the settlement payment relation."},{"object_id":"x_delta_pm_deviation","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Delta P^M_{mt} is the deviation defined in Eq. (7) and used to determine the settlement penalty; it is part of the settlement.payment computation."},{"object_id":"x_delta_pm_positive","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Delta P^{M+}_{mt} is the positive deviation quantity multiplied by nu_m in the settlement penalty term."},{"object_id":"x_delta_indicator","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"delta_{mt} is the binary selector that determines whether the positive deviation is penalized; it implements the conditional branch of settlement.payment."},{"object_id":"theta_nu_penalty","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"nu_m is the penalty coefficient multiplying the positive deviation in the settlement.payment term."},{"object_id":"theta_pdm_assigned","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"PD^M_{mt} is the DMO-assigned power to microgrid m, the reference value for the settlement deviation."},{"object_id":"theta_pm_max","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"P^{M,max} is the transfer limit used to bound the deviation-selection constraints for settlement.payment."},{"object_id":"theta_epsilon","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"epsilon is the small positive offset in Eq. (10) used to enforce the one-sided penalty branch of settlement.payment."},{"object_id":"v141-c-R010-C001","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The penalty term nu_m Delta P^{M+}_{mt} is the payment charge for positive deviation under settlement.payment."},{"object_id":"v141-c-R010-C002","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The negative-deviation exemption is represented by Delta P^{M+}=0 when Delta P^M\u003c0, so settlement.payment charges no deviation penalty."},{"object_id":"v141-c-R010-C003","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"The alternative penalty basis |Delta P^M| is attached to settlement.payment as the absolute-deviation variant."},{"object_id":"v141-c-R010-C004","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eq. (7) defines the deviation used by settlement.payment."},{"object_id":"v141-c-R010-C005","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"Eqs. (8)-(10) implement the binary selection of the positive deviation charged by settlement.payment."}],"revision_requests":[]}},"quarantined_references":[]}});
